<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $labels=['SCHEDULED'=>'Menunggu','IN_PROGRESS'=>'Sedang Diperiksa','COMPLETED'=>'Selesai','CANCELLED'=>'Dibatalkan']; ?>
