<a class="stat-card" style="text-decoration:none;color:inherit" href="<?= base_url('index.php?c=emr&status='.$status) ?>"><div class="top"><span><?= $label ?></span></div><div class="num"><?= (int)$stats[$key] ?></div><div class="desc"><span class="badge badge-<?= $tone ?>"><?= (int)$stats[$key] ?> <?= $badge ?></span><span><?= $detail ?></span></div></a><?php endforeach; ?></div>
<div class="card" style="padding:16px 20px;margin-bottom:20px"><form method="get" action="<?= base_url('index.php') ?>" style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><input type="hidden" name="c" value="emr"><input type="hidden" name="mode" value="<?= $patientMode?'patients':'queue' ?>">
<div style="flex:1;min-width:160px"><label class="form-label" for="poli">Poliklinik</label><select class="form-control" id="poli" name="policlinic_id"><option value="">-- Semua Poliklinik --</option><?php foreach($policlinics as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $filters['policlinic_id']==$p['id']?'selected':'' ?>><?= $e($p['name']) ?></option><?php endforeach; ?></select></div>
<div style="flex:1;min-width:180px"><label class="form-label" for="doctor">Dokter Pemeriksa</label><select class="form-control" id="doctor" name="doctor_id"><option value="">-- Semua Dokter --</option><?php foreach($doctors as $d): ?><option value="<?= (int)$d['id'] ?>" <?= $filters['doctor_id']==$d['id']?'selected':'' ?>><?= $e($d['full_name']) ?></option><?php endforeach; ?></select></div>
