<button class="btn btn-primary"><i data-lucide="filter"></i>Terapkan Filter</button><a class="btn btn-outline" href="<?= base_url('index.php?c=emr') ?>"><i data-lucide="rotate-ccw"></i>Reset</a>
<div style="display:flex;width:100%;gap:12px;align-items:end;flex-wrap:wrap"><div style="flex:1;min-width:220px"><label for="patient-search" class="form-label">Cari Pasien (No. RM / NIK / Nama)</label><input class="form-control" id="patient-search" name="q" value="<?= $e($search) ?>" placeholder="Masukkan nomor RM, NIK, atau nama pasien"></div><button class="btn btn-outline">Cari Pasien</button><a class="btn btn-outline" href="<?= base_url('index.php?c=emr&mode='.($patientMode?'queue':'patients').'&q='.urlencode($search)) ?>"><?= $patientMode?'Lihat Antrean Kunjungan':'Daftar Semua Pasien' ?></a></div></form></div>
<div class="card" style="padding:0;overflow:hidden"><div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between"><b style="color:var(--blue-900)"><?= $patientMode?'Daftar Pasien Terdaftar':'Antrean Pasien Poliklinik' ?></b><span class="badge badge-primary"><?= (int)$pagination['total'] ?> <?= $patientMode?'Pasien':'Kunjungan' ?> Terdata</span></div><div class="table-responsive"><table class="table"><thead><tr><?php if(!$patientMode): ?><th>No. Antre</th><?php endif; ?><th>No. RM</th><th>Identitas Pasien</th><?php if($patientMode): ?><th>Kunjungan</th><?php else: ?><th>Poli / Dokter Spesialis</th><th>Jaminan</th><th>Status Kunjungan</th><th>Diagnosa Terakhir</th><?php endif; ?><th>Aksi Medis</th></tr></thead><tbody>
<?php foreach($rows as $r): $pid=(int)($r['patient_id'] ?? $r['id']); ?><tr><?php if(!$patientMode): ?><td><?= $e($r['queue_number']) ?><br><small><?= format_date_id($r['appointment_date']) ?></small></td><?php endif; ?><td><b><?= $e($r['no_rm']) ?></b></td><td><b><?= $e($r['patient_name'] ?? $r['full_name']) ?></b><div style="font-size:11.5px;color:var(--muted)"><?= $r['gender']==='L'?'Laki-laki':'Perempuan' ?> · <?= format_date_id($r['birth_date']) ?></div></td>
<?php if($patientMode): ?><td><?= (int)$r['visit_count'] ?></td><?php else: ?><td><?= $e($r['policlinic_name']) ?><div style="font-size:11.5px;color:var(--muted)"><?= $e($r['doctor_name']) ?></div></td><td><span class="badge badge-secondary"><?= $e($r['insurance_type']) ?></span></td><td><span class="badge <?= $r['status']==='COMPLETED'?'badge-success':($r['status']==='SCHEDULED'?'badge-warning':'badge-info') ?>"><?= $e($labels[$r['status']] ?? $r['status']) ?></span></td><td><?= $e($r['icd10_code'] ?: 'Belum diisi') ?><div style="font-size:11.5px;color:var(--muted)"><?= $e($r['diagnosis_name'] ?? '') ?></div></td><?php endif; ?>
<td><div style="display:flex;gap:6px"><a class="btn btn-primary" href="<?= base_url('index.php?c=emr&a='.($patientMode?'visits&patient_id='.$pid:'examine&id='.(int)$r['id'])) ?>"><?= $patientMode?'Pilih Pasien':($r['status']==='COMPLETED'?'Buka EMR':'Periksa') ?></a><a class="btn btn-outline" title="Riwayat dan kunjungan" href="<?= base_url('index.php?c=emr&a=visits&patient_id='.$pid) ?>"><i data-lucide="history"></i></a></div></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="8" style="text-align:center;padding:48px 20px;color:var(--muted)">Tidak ada data untuk kriteria filter ini. Klik Reset atau Daftar Semua Pasien untuk mencari pasien yang sudah terdaftar.</td></tr><?php endif; ?></tbody></table></div><?php require __DIR__.'/../components/pagination.php'; ?></div>
